def _is_nonempty_str(value):
    return isinstance(value, str) and value != ""


# 拒绝记录的 phase 按异常类型归类：请求结构类 → request，资源/引用类 →
# validation，term_maps 字段或同源冲突类 → mapping。
REJECTION_PHASES = (
    (InputError, "request"),
    (FhirValidationError, "validation"),
    (TermMappingError, "mapping"),
)


def _rejection_phase(exc):
    for error_cls, phase in REJECTION_PHASES:
        if isinstance(exc, error_cls):
            return phase
    return None


def build_rejection_record(raw_text, exc):
    """为请求处理失败构造 decision=rejected 的审计记录。

    仅保留 audit_context 三值（任一缺失/为空则三项均为 null），不写入
    resource、term_maps、引用、message 或请求正文。
    """
    request_id = None
    actor = None
    recorded_at = None
    try:
        request = json.loads(raw_text)
    except (json.JSONDecodeError, ValueError):
        request = None
    if isinstance(request, dict):
        audit_context = request.get("audit_context")
        if isinstance(audit_context, dict):
            values = [
                audit_context.get(field)
                for field in ("request_id", "actor", "recorded_at")
            ]
            if all(_is_nonempty_str(value) for value in values):
                request_id, actor, recorded_at = values

    return {
        "request_id": request_id,
        "actor": actor,
        "recorded_at": recorded_at,
        "decision": "rejected",
        "audit_id": uuid.uuid4().hex,
        "error_type": type(exc).__name__,
        "phase": _rejection_phase(exc),
        "status": 400,
    }


def append_rejection_record(audit_path, chained, raw_text, exc):
    """追加拒绝审计记录；链式模式沿用规范 JSON 与 SHA-256 链。"""
    record = build_rejection_record(raw_text, exc)
    if chained:
        append_chained_audit_line(audit_path, record)
    else:
        append_audit_line(audit_path, record)

